-- Decode program
local pb=b64(PR)
if not pb or #pb<16414then error("[VM]")return end
local prog={}for pi=1,#pb,2 do prog[#prog+1]=pb[pi]+pb[pi+1]*256 end

-- Decode data
local db=b64(DT)
if not db or #db<131312then error("[VM]")return end

-- ==========================================
-- STEP 1: Reverse global permutation
-- ==========================================
do
 local tmp={}
 for bi=1,#db do tmp[bi]=IPM[db[bi]+1]or db[bi]end
 db=tmp
end

-- ==========================================
-- STEP 2: Reverse 8 S-box rounds (reverse order)
-- ==========================================
for round=7,0,-1 do
 local tbl
 if round==7then tbl=IS7
 elseif round==6then tbl=IS6
 elseif round==5then tbl=IS5
 elseif round==4then tbl=IS4
 elseif round==3then tbl=IS3
 elseif round==2then tbl=IS2
 elseif round==1then tbl=IS1
 else tbl=IS0 end
 
 local tmp={}for bi=1,#db do tmp[bi]=tbl[db[bi]+1]or db[bi]end
 db=tmp
end

-- ==========================================
-- STEP 3: Reverse 100 XOR layers
-- ==========================================
-- Reassemble into blocks first
local num_blocks=8207
local block_size=16

for step=1,num_blocks do
 -- Get original block index
 local orig_idx=prog[step]-1
 if not orig_idx then break end
 
 local off=(step-1)*block_size
 if off+block_size>#db then break end
 
 -- Extract block
 local blk={}for bi=1,block_size do blk[bi]=db[off+bi]or 0 end
 
 -- Reverse XOR layers (last to first)
 for layer=100-1,0,-1 do
  local key=kdf(SEED,layer*7+13,32)
  for bi=1,block_size do
   blk[bi]=bx(blk[bi],key[(bi+orig_idx)%#key+1])
  end
 end
 
 -- Write back decrypted
 for bi=1,block_size do
  output_idx=off+bi
  db[output_idx]=blk[bi]
 end
end

-- ==========================================
-- INTEGRITY CHECK
-- ==========================================
local vs=0 for vi=1,#db do vs=(vs+db[vi]*vi)%4294967291 end
if tostring(vs)!="1109551127"then error("[VM]T")return end

-- Remove padding
while #db>0 and db[#db]>=1 and db[#db]<=16 do
 local pl=db[#db]
 local valid=true
 for ci=#db-pl+1,#db do if db[ci]~=pl then valid=false break end end
 if valid then
  for _=1,pl do table.remove(db)end
 else break end
end

while #db>0 and db[#db]==0 do table.remove(db)end

-- Execute
local code=string.char(unpack(db))
local fn,err=(loadstring or load)(code)
if fn then fn()else error(tostring(err))end